import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, idx, T, DUR, Camara, Textura, Profundidad, Brillo, Paso, tono, Chip, Ondas, Destello, golpe, Easing, interpolate, clamp, h, FONT} from './kit';

// ---------- utilidades ----------
const cl = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const eo = (x: number) => 1 - Math.pow(1 - cl(x), 3);
const eio = (x: number) => { const k = cl(x); return k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2; };
const ro = (s: number, a: number, b: number) => cl((s - a) / (b - a));
// parada de camara que nunca deja ver el borde del fondo
const P = (t: number, x: number, y: number, z: number) => ({t, x: cl(x, 540 / z, 1080 - 540 / z), y: cl(y, 1000 / z, 1920 - 920 / z), zoom: z});
// donde cae el punto (x,y) del mundo en pantalla bajo una parada de camara
const scr = (c: {x: number; y: number; zoom: number}, x: number, y: number) => ({x: 540 + (x - c.x) * c.zoom, y: 1000 + (y - c.y) * c.zoom});
const GOLD = '#FFC83D';
const RED = '#FF4D4D';
const PIELES = [['#f3d2b0', '#e3b88e', '#c99a6e'], ['#e0a878', '#c98f5e', '#9c6a40'], ['#b57b52', '#8a5a36', '#5e3a22'], ['#7a4f2c', '#5e3a22', '#3d2414'], ['#fffaf0', '#ece2c8', '#c4b68e']];
// SFX: nunca dos a menos de 0,27 s aunque la voz real cambie los tiempos
const fix = (l: {t: number; s: string}[]) => {
  const o: {t: number; s: string}[] = [];
  let last = -9;
  [...l].sort((a, b) => a.t - b.t).forEach((e) => { if (e.t - last >= 0.27) { o.push(e); last = e.t; } });
  return o;
};
const sf = (p: string, s: string, o = 0, n = 1) => ({t: en(p, n) + o, s});

// ---------- tiempos (todo atado a palabras del guion) ----------
const VENDIO = en('vendio'), EIFFEL = en('eiffel'), DESPUES = en('despues'), OTRA = en('otra');
const PARIS = en('paris'), VIEJA = en('vieja'), COSTABA = en('costaba'), VICTOR = en('victor'), LUSTIG1 = en('lustig'), LEYO = en('leyo'), PERIODICO = en('periodico');
const SEHIZO = T(idx('hizo') - 1), FUNCIONARIO = en('funcionario'), GOBIERNO = en('gobierno'), REUNIO = en('reunio'), CHATARRA = en('chatarra'), HOTEL = en('hotel'), DESARMAR = en('desarmar'), HIERRO = en('hierro');
const E4S = T(idx('nadie') - 2), NADIE = en('nadie'), OIDO = en('oido'), ERA = en('era'), SECRETO1 = en('secreto'), DIJO2 = en('dijo', 2), SABIA = en('sabia'), GENTE = en('gente'), PROTESTAR = en('protestar');
const E5S = T(idx('comerciante') - 1), POISSON1 = en('poisson'), PAGO = en('pago'), LUSTIG2 = en('lustig', 2), FUE = en('fue'), DINERO = en('dinero');
const AQUI = en('aqui'), AQUI0 = T(idx('aqui') - 1), POISSON2 = en('poisson', 2), NUNCA = en('nunca'), DENUNCIO = en('denuncio'), VERGUENZA = en('verguenza');
const MESES = en('meses'), VOLVIO = en('volvio'), COMPRADORES = en('compradores'), UNO = en('uno'), POLICIA = en('policia'), HUYO = en('huyo');
const SECRETO2 = en('secreto', 2), PRISA = en('prisa'), UNICA = en('unica'), MISMAS = en('mismas'), SENALES = en('senales'), HOY = en('hoy');
const DALE = en('dale'), SECRETO3 = en('secreto', 3), ENVIASELO = en('enviaselo'), UNICAS = en('unicas');

// ---------- piezas dibujadas ----------
const Polvo: React.FC<{n?: number; color?: string; vel?: number}> = ({n = 30, color = 'rgba(255,240,210,0.5)', vel = 1}) => {
  const {s} = useS();
  return (
    <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
      {Array.from({length: n}).map((_, i) => {
        const x = h(i * 3 + 1) * 1080 + Math.sin(s * 0.6 + i) * 34;
        const y = (((h(i * 7 + 2) * 1920 - s * (14 + h(i) * 26) * vel) % 1920) + 1920) % 1920;
        return <circle key={i} cx={x} cy={y} r={2 + h(i * 5) * 4} fill={color} opacity={0.25 + h(i * 11) * 0.4} />;
      })}
    </svg>
  );
};

// mano con el dedo indice arriba; piel = 0 clara, 1 canela, 2 morena, 3 oscura, 4 guante; manga = color de la manga del traje
const Mano: React.FC<{x: number; y: number; r?: number; k?: number; dedo?: boolean; piel?: number; manga?: string}> = ({x, y, r = 0, k = 1, dedo = true, piel = 1, manga}) => {
  const C = PIELES[piel];
  const F = `url(#pl${piel})`;
  const L = C[2];
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
      <defs><linearGradient id={`pl${piel}`} x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor={C[0]} /><stop offset="55%" stopColor={C[1]} /><stop offset="100%" stopColor={C[2]} /></linearGradient></defs>
      <rect x={-64} y={80} width={128} height={420} rx={50} fill={F} stroke={L} strokeWidth={4} />
      <rect x={-80} y={-70} width={160} height={190} rx={56} fill={F} stroke={L} strokeWidth={4} />
      {[[-58, 70], [-20, 55], [20, 60], [58, 75]].map(([fx, fl], i) => (
        <rect key={i} x={fx - 17} y={-70 - (i === 1 && dedo ? 150 : fl)} width={34} height={(i === 1 && dedo ? 150 : fl) + 40} rx={17} fill={F} stroke={L} strokeWidth={3} />
      ))}
      <rect x={-128} y={-20} width={34} height={110} rx={17} fill={F} stroke={L} strokeWidth={3} transform="rotate(-38 -110 60)" />
      <path d="M -80 -20 Q -30 -50 20 -20" stroke="rgba(255,255,255,0.28)" strokeWidth={6} fill="none" strokeLinecap="round" />
      {manga && (
        <g>
          <rect x={-76} y={118} width={152} height={420} rx={16} fill={manga} stroke="rgba(0,0,0,0.4)" strokeWidth={3} />
          <rect x={-80} y={104} width={160} height={34} rx={9} fill="#f4f0e6" stroke="#bdb7a4" strokeWidth={3} />
        </g>
      )}
    </g>
  );
};

// hoja de papel
const Papel: React.FC<{x: number; y: number; w: number; hh: number; r?: number; fill?: string; borde?: string; children?: React.ReactNode}> = ({x, y, w, hh, r = 0, fill = '#f4efe3', borde = '#b9ad8f', children}) => (
  <g transform={`translate(${x} ${y}) rotate(${r})`}>
    <rect x={-w / 2 + 8} y={-hh / 2 + 14} width={w} height={hh} rx={12} fill="rgba(0,0,0,0.38)" />
    <rect x={-w / 2} y={-hh / 2} width={w} height={hh} rx={12} fill={fill} stroke={borde} strokeWidth={4} />
    {children}
  </g>
);

// etiqueta de precio con cordon
const Etq: React.FC<{x: number; y: number; txt: string; r?: number; k?: number; fs?: number; color?: string}> = ({x, y, txt, r = 0, k = 1, fs = 40, color = '#f6ecd2'}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <path d="M 0 -150 Q -30 -100 0 -60" stroke="#8a6a10" strokeWidth={5} fill="none" />
    <path d="M -90 -60 L 90 -60 L 120 -20 L 120 70 L -120 70 L -120 -20 Z" fill="rgba(0,0,0,0.3)" transform="translate(8 10)" />
    <path d="M -90 -60 L 90 -60 L 120 -20 L 120 70 L -120 70 L -120 -20 Z" fill={color} stroke="#b79a52" strokeWidth={5} />
    <circle cy={-34} r={11} fill="#3a2a00" />
    <text y={46} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={fs} fill="#6b5524">{txt}</text>
  </g>
);

// el contrato: papel amarillento con sello falso (estrella y aro, sin escudo real)
const Contrato: React.FC<{x: number; y: number; k?: number; r?: number; plegado?: number}> = ({x, y, k = 1, r = 0, plegado = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k} ${k * (1 - 0.66 * plegado)})`}>
    <rect x={-122} y={-162} width={260} height={340} rx={10} fill="rgba(0,0,0,0.35)" />
    <rect x={-130} y={-170} width={260} height={340} rx={10} fill="#e9d6a4" stroke="#9a7b3c" strokeWidth={5} />
    <text y={-125} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={27} fill="#5a3f12">CONTRATO</text>
    {[0, 1, 2, 3, 4].map((i) => <rect key={i} x={-92} y={-92 + i * 30} width={i === 4 ? 120 : 184} height={8} rx={4} fill="rgba(90,60,20,0.45)" />)}
    <path d="M -95 110 q 20 -30 35 0 q 15 -25 30 -2" stroke="#3a2a10" strokeWidth={4} fill="none" strokeLinecap="round" />
    <g transform="translate(70 100)">
      <circle r={42} fill="none" stroke="#a3262a" strokeWidth={6} />
      <circle r={30} fill="none" stroke="#a3262a" strokeWidth={2.5} />
      <polygon points="0,-22 6,-7 22,-7 9,3 14,19 0,9 -14,19 -9,3 -22,-7 -6,-7" fill="#a3262a" opacity={0.85} />
    </g>
    <path d="M -130 -170 L -20 -170 L -130 40 Z" fill="rgba(255,255,255,0.18)" />
    {plegado > 0 && [-57, 57].map((cy) => <line key={cy} x1={-130} y1={cy} x2={130} y2={cy} stroke="rgba(90,60,20,0.6)" strokeWidth={3} opacity={cl(plegado * 3)} />)}
  </g>
);

// sombrero de fieltro (origen: centro del ala)
const Sombrero: React.FC<{x: number; y: number; k?: number; r?: number}> = ({x, y, k = 1, r = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <ellipse cy={10} rx={96} ry={14} fill="rgba(0,0,0,0.3)" />
    <path d="M -54 0 Q -60 -74 -30 -82 Q 0 -68 30 -82 Q 60 -74 54 0 Z" fill="#4a4a54" stroke="#2a2a32" strokeWidth={3} />
    <rect x={-55} y={-28} width={110} height={18} fill="#1a1a20" />
    <ellipse rx={96} ry={20} fill="#3a3a44" stroke="#2a2a32" strokeWidth={3} />
    <path d="M -30 -60 Q -10 -70 6 -62" stroke="rgba(255,255,255,0.25)" strokeWidth={5} fill="none" strokeLinecap="round" />
  </g>
);

// Victor Lustig: bigote, sombrero, piel clara; mira hacia abajo, al periodico
const Lustig: React.FC<{x: number; y: number; k?: number; mira?: number}> = ({x, y, k = 1, mira = 0}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <path d="M -230 330 Q -220 150 -80 118 L 80 118 Q 220 150 230 330 Z" fill="#2e2e36" stroke="#1a1a20" strokeWidth={4} />
    <path d="M -50 118 L 0 220 L 50 118 Z" fill="#f4f0e6" />
    <path d="M -8 130 L 8 130 L 14 230 L 0 252 L -14 230 Z" fill="#a3262a" />
    <rect x={-30} y={60} width={60} height={70} fill="#e3b88e" />
    <circle cx={-103} cy={4} r={22} fill="#e3b88e" stroke="#c99a6e" strokeWidth={3} />
    <circle cx={103} cy={4} r={22} fill="#e3b88e" stroke="#c99a6e" strokeWidth={3} />
    <circle r={105} fill="#f0cba5" stroke="#c99a6e" strokeWidth={4} />
    <path d="M -70 40 Q 0 110 70 40" stroke="rgba(160,100,70,0.25)" strokeWidth={14} fill="none" />
    {[-36, 36].map((ex) => (
      <g key={ex}>
        <ellipse cx={ex} cy={-2} rx={22} ry={14} fill="#fff" stroke="#8a6a50" strokeWidth={2} />
        <circle cx={ex + Math.sin(mira) * 7} cy={4 + Math.abs(Math.cos(mira)) * 2} r={9} fill="#2a1a10" />
        <circle cx={ex + Math.sin(mira) * 7 + 3} cy={1 + Math.abs(Math.cos(mira)) * 2} r={3} fill="#fff" />
        <path d={`M ${ex - 26} -24 Q ${ex} -38 ${ex + 26} -24`} stroke="#3a2416" strokeWidth={7} fill="none" strokeLinecap="round" />
      </g>
    ))}
    <path d="M 0 -6 Q -14 30 6 34" stroke="#b98a64" strokeWidth={5} fill="none" strokeLinecap="round" />
    <path d="M 0 52 C -30 28 -90 30 -104 62 C -70 56 -30 58 0 62 C 30 58 70 56 104 62 C 90 30 30 28 0 52 Z" fill="#2a1a10" />
    <path d="M -20 82 Q 0 90 20 82" stroke="#8a4a3a" strokeWidth={5} fill="none" strokeLinecap="round" />
    <Sombrero x={0} y={-72} k={1.9} />
  </g>
);

// la Torre Eiffel de hierro con remaches; sep(i) separa cada tramo (para desarmarla). Origen: centro de la base.
const TH = 1280;
const hw = (u: number) => 14 + 366 * Math.pow(1 - u, 2.4);
const Torre: React.FC<{x: number; y: number; k?: number; sep?: (i: number) => {dx: number; dy: number; r: number; o: number}; n?: number}> = ({x, y, k = 1, sep, n = 8}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    {Array.from({length: n}).map((_, i) => {
      const u0 = i / n, u1 = (i + 1) / n;
      const a0 = hw(u0), a1 = hw(u1), y0 = -u0 * TH, y1 = -u1 * TH;
      const cy = (y0 + y1) / 2;
      const o = sep ? sep(i) : {dx: 0, dy: 0, r: 0, o: 1};
      return (
        <g key={i} transform={`translate(${o.dx} ${o.dy}) rotate(${o.r} 0 ${cy})`} opacity={o.o}>
          <polygon points={`${-a0},${y0} ${a0},${y0} ${a1},${y1} ${-a1},${y1}`} fill="rgba(76,56,36,0.62)" stroke="#2c1e10" strokeWidth={8} strokeLinejoin="round" />
          <line x1={-a0} y1={y0} x2={a1} y2={y1} stroke="#2c1e10" strokeWidth={6} />
          <line x1={a0} y1={y0} x2={-a1} y2={y1} stroke="#2c1e10" strokeWidth={6} />
          <line x1={-a0} y1={y0} x2={-a1} y2={y1} stroke="rgba(255,225,170,0.55)" strokeWidth={4} />
          {i === 0 && <path d={`M ${-a0 * 0.55} 0 Q 0 ${-(TH / n) * 1.7} ${a0 * 0.55} 0`} stroke="#2c1e10" strokeWidth={9} fill="none" />}
          {(i === 2 || i === 4) && <rect x={-a1 - 14} y={y1 - 11} width={a1 * 2 + 28} height={22} rx={5} fill="#b59563" stroke="#2c1e10" strokeWidth={4} />}
          {i === n - 1 && <g><line x1={0} y1={y1} x2={0} y2={y1 - 90} stroke="#2c1e10" strokeWidth={6} /><circle cy={y1 - 96} r={8} fill="#e0bf82" stroke="#2c1e10" strokeWidth={3} /></g>}
          {[[-a0, y0], [a0, y0], [-a1, y1], [a1, y1]].map(([px, py], j) => <circle key={j} cx={px} cy={py} r={6} fill="#e0bf82" stroke="#2c1e10" strokeWidth={2} />)}
        </g>
      );
    })}
  </g>
);

const Fajo: React.FC<{x: number; y: number; k?: number; r?: number}> = ({x, y, k = 1, r = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <rect x={-46} y={-26} width={92} height={56} rx={6} fill="rgba(0,0,0,0.35)" transform="translate(4 6)" />
    <rect x={-46} y={-30} width={92} height={56} rx={6} fill="#d8c48e" stroke="#7a6630" strokeWidth={3} />
    <rect x={-46} y={-30} width={92} height={22} rx={6} fill="#c7b078" />
    <rect x={-12} y={-30} width={24} height={56} fill="#a3262a" opacity={0.85} />
    <text y={10} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={22} fill="#5a4a1a">FR</text>
  </g>
);

// maletin visto de frente y un poco desde arriba; abre = 0 cerrado, 1 abierto
const Maletin: React.FC<{abre: number; llenos: number}> = ({abre, llenos}) => {
  const L = 190 * abre;
  return (
    <g>
      <ellipse cy={165} rx={250} ry={22} fill="rgba(0,0,0,0.4)" />
      {abre > 0.04 && <polygon points={`-165,-92 165,-92 188,${-92 - L} -188,${-92 - L}`} fill="#5a1a1a" stroke="#2c180a" strokeWidth={5} />}
      <polygon points="-190,0 190,0 165,-92 -165,-92" fill={abre > 0.04 ? '#2a0d0d' : '#9a6a3a'} stroke="#2c180a" strokeWidth={5} />
      {abre <= 0.04 && <path d="M -60 -92 Q 0 -150 60 -92" stroke="#2c180a" strokeWidth={14} fill="none" strokeLinecap="round" />}
      {abre > 0.04 && Array.from({length: 4}).map((_, i) => {
        const a = cl(llenos * 4 - i);
        return a > 0 ? <Fajo key={i} x={-105 + i * 70} y={-46 - (1 - a) * 20} k={0.72 * a} /> : null;
      })}
      <rect x={-190} y={0} width={380} height={150} rx={20} fill="#8a5a2c" stroke="#2c180a" strokeWidth={5} />
      <rect x={-172} y={14} width={344} height={122} rx={12} fill="none" stroke="#d9b07a" strokeWidth={3} strokeDasharray="12 9" opacity={0.85} />
      {[-95, 95].map((lx) => <rect key={lx} x={lx - 22} y={0} width={44} height={40} rx={8} fill={GOLD} stroke="#7a5a10" strokeWidth={3} />)}
      {[[-190, 0], [190, 0], [-190, 150], [190, 150]].map(([cx, cy], i) => <circle key={i} cx={cx} cy={cy} r={14} fill="#c9a24a" stroke="#7a5a10" strokeWidth={3} />)}
      <path d="M -190 20 Q 0 50 190 20 L 190 0 L -190 0 Z" fill="rgba(255,255,255,0.12)" />
    </g>
  );
};

const Cartera: React.FC<{x: number; y: number; k?: number}> = ({x, y, k = 1}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <defs>
      <linearGradient id="cuero15" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8a5a34" /><stop offset="60%" stopColor="#5f3a1f" /><stop offset="100%" stopColor="#3d2312" /></linearGradient>
    </defs>
    <ellipse cx={0} cy={140} rx={210} ry={26} fill="rgba(0,0,0,0.4)" />
    <rect x={-190} y={-120} width={380} height={250} rx={30} fill="url(#cuero15)" stroke="#2c180a" strokeWidth={5} />
    <rect x={-170} y={-100} width={340} height={210} rx={20} fill="none" stroke="#c9a074" strokeWidth={3} strokeDasharray="12 9" opacity={0.85} />
    <path d="M -190 -40 Q 0 -10 190 -40 L 190 -80 Q 0 -110 -190 -80 Z" fill="rgba(255,255,255,0.10)" />
    <rect x={120} y={-24} width={70} height={64} rx={14} fill={GOLD} stroke="#2c180a" strokeWidth={4} />
    <circle cx={152} cy={8} r={12} fill="#fff2b0" />
  </g>
);

// ================= SITIO 1: la torre con etiquetas (E1) =================
const S1_CAM = [P(0, 540, 1300, 1.2), P(VENDIO, 540, 1180, 1.3), P(OTRA - 0.2, 540, 930, 1.45), P(PARIS - 0.4, 540, 800, 1.55)];
const S1_END = S1_CAM[3];
const Sitio1: React.FC = () => {
  const {s, spr} = useS();
  const a1 = spr(VENDIO, 11, 150), a2 = spr(OTRA, 11, 150);
  const l1 = ro(s, VENDIO + 0.5, VENDIO + 1.2), l2 = ro(s, OTRA + 0.5, OTRA + 1.2);
  const tiembla = golpe(s, 0.1, 22, 6) * 9;
  const etq = (fx: number, fy: number, r: number, a: number, lift: number, txt: string, ini: number) => (s < ini - 0.2 ? null : (
    <g>
      <Etq x={fx} y={fy - (1 - a) * 1300} r={r} txt={txt} fs={40} />
      <Mano x={fx} y={fy - (1 - a) * 1300 - 232 - eo(lift) * 1400} r={180} k={0.55} dedo={false} piel={4} />
    </g>
  ));
  return (
    <AbsoluteFill>
      <Camara paradas={S1_CAM}>
        <Textura tipo="papel" base="linear-gradient(180deg, #4d3520 0%, #a97b45 50%, #e3c48c 100%)" linea="rgba(80,50,20,0.5)" luz="rgba(255,225,160,0.30)" semilla={31} />
        <Brillo x={540} y={720} r={640} color="rgba(255,235,190,0.45)" />
        <Brillo x={110} y={1400} r={230} color="rgba(255,205,110,0.5)" />
        <Brillo x={970} y={1400} r={230} color="rgba(255,205,110,0.5)" />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <defs><linearGradient id="nb1" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#ebd7af" stopOpacity={0} /><stop offset="100%" stopColor="#ebd7af" stopOpacity={0.8} /></linearGradient></defs>
          <rect x={0} y={1720} width={1080} height={200} fill="#2a1b0c" />
          {Array.from({length: 9}).map((_, i) => <line key={i} x1={i * 140 - 40} y1={1720} x2={i * 190 - 300} y2={1920} stroke="rgba(255,220,150,0.15)" strokeWidth={4} />)}
          {[110, 970].map((lx, i) => (
            <g key={lx}>
              <rect x={lx - 7} y={1400} width={14} height={330} fill="#241709" />
              <path d={`M ${lx - 34} 1400 L ${lx + 34} 1400 L ${lx + 22} 1350 L ${lx - 22} 1350 Z`} fill="#241709" />
              <circle cx={lx} cy={1378} r={16 + Math.sin(s * 7 + i * 2) * 1.5} fill="#ffe3a0" />
            </g>
          ))}
          <g transform={`translate(${tiembla} 0)`}><Torre x={540} y={1720} /></g>
          {etq(430, 1330, -7, a1, l1, 'VENDIDA', VENDIO)}
          {etq(655, 1085, 6, a2, l2, 'OTRA VEZ', OTRA)}
          {[0, 1, 2].map((i) => <rect key={i} x={-300 + ((s * (24 + i * 10) + i * 420) % 1700)} y={1560 + i * 70} width={720} height={150} rx={75} fill="url(#nb1)" />)}
        </svg>
        <Polvo n={26} color="rgba(255,235,190,0.55)" />
      </Camara>
    </AbsoluteFill>
  );
};

// ================= SITIO 2: periodico y Lustig (E2) =================
