const S5A_CAM = [P(SECRETO2 - 0.4, 540, 1000, 1.0), P(SECRETO2, 540, 800, 1.5), P(PRISA, 540, 1000, 1.5), P(UNICA, 540, 1200, 1.5), P(SENALES, 540, 1000, 1.15)];
