const Sitio5: React.FC = () => {
  const {s, spr} = useS();
  const burn = ro(s, MISMAS, HOY + 0.6);
  const yF = 1700 - burn * 1450;
  const borde = Array.from({length: 37}).map((_, i) => [i * 30, yF + 26 * Math.sin(i * 0.9 + s * 6) + 20 * h(i + 3) - 10] as [number, number]);
  const clip = `0,-200 1080,-200 ${borde.slice().reverse().map((p) => p.join(',')).join(' ')}`;
  const quema = burn > 0 && burn < 1;
  const cartera = eo(ro(s, DALE - 0.1, DALE + 0.6));
  const palabra = (txt: string, t: number, y: number, key: number) => {
    const a = cl(spr(t, 9, 190), 0, 1.4);
    if (s < t - 0.05) return null;
    return (
      <g key={txt} transform={`translate(${540 + golpe(s, t, 44, 8) * 12} ${y}) scale(${1 + (1 - a) * 1.4})`} opacity={cl(a * 2)}>
        <rect x={-310} y={-70} width={620} height={140} rx={22} fill="rgba(58,38,10,0.9)" stroke={GOLD} strokeWidth={8} />
        <rect x={-292} y={-54} width={584} height={108} rx={14} fill="none" stroke="rgba(255,200,61,0.45)" strokeWidth={3} />
        <text y={30} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={key > 1 ? 100 : 92} fill={GOLD}>{txt}</text>
      </g>
    );
  };
  return (
    <AbsoluteFill>
      <Camara paradas={S5B_CAM}>
        <Textura tipo="papel" base="linear-gradient(180deg, #4d3520 0%, #a97b45 50%, #e3c48c 100%)" linea="rgba(80,50,20,0.5)" luz="rgba(255,225,160,0.30)" semilla={31} />
        <Brillo x={540} y={720} r={640} color="rgba(255,235,190,0.45)" />
        <Brillo x={110} y={1400} r={230} color="rgba(255,205,110,0.5)" />
        <Brillo x={970} y={1400} r={230} color="rgba(255,205,110,0.5)" />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <defs><linearGradient id="nb5" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#ebd7af" stopOpacity={0} /><stop offset="100%" stopColor="#ebd7af" stopOpacity={0.8} /></linearGradient></defs>
          <rect x={0} y={1720} width={1080} height={200} fill="#2a1b0c" />
          {[110, 970].map((lx, i) => (
            <g key={lx}>
              <rect x={lx - 7} y={1400} width={14} height={330} fill="#241709" />
              <path d={`M ${lx - 34} 1400 L ${lx + 34} 1400 L ${lx + 22} 1350 L ${lx - 22} 1350 Z`} fill="#241709" />
              <circle cx={lx} cy={1378} r={16 + Math.sin(s * 7 + i * 2) * 1.5} fill="#ffe3a0" />
            </g>
          ))}
          <Torre x={540} y={1720} />
          {[0, 1, 2].map((i) => <rect key={i} x={-300 + ((s * (24 + i * 10) + i * 420) % 1700)} y={1560 + i * 70} width={720} height={150} rx={75} fill="url(#nb5)" />)}
        </svg>
        <Polvo n={26} color="rgba(255,235,190,0.55)" />
      </Camara>
      <AbsoluteFill style={{opacity: cartera, transform: `translateY(${(1 - cartera) * 500}px)`}}>
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <g transform={`translate(0 ${Math.sin(s * 2.4) * 8})`}><Cartera x={540} y={1640} k={1.25} /></g>
        </svg>
        <Brillo x={540} y={1640} r={380} color="rgba(255,200,61,0.3)" />
      </AbsoluteFill>
      <Chip texto="SECRETO" x={540} y={560} t0={SECRETO3} t1={9999} color={GOLD} size={100} />
      <Ondas x={540} y={1600} t0={DALE} color={GOLD} radio={380} />
      <Ondas x={540} y={1600} t0={ENVIASELO} color={GOLD} radio={380} />
      {s < HOY + 1.4 && (
        <AbsoluteFill>
          <Camara paradas={S5A_CAM}>
            <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
              <defs>
                <clipPath id="quema15"><polygon points={clip} /></clipPath>
                <radialGradient id="fondo15" cx="50%" cy="50%" r="70%"><stop offset="0%" stopColor="#5a3f1c" /><stop offset="70%" stopColor="#20140a" /><stop offset="100%" stopColor="#0c0603" /></radialGradient>
              </defs>
              <g clipPath="url(#quema15)">
                <rect x={-600} y={-700} width={2280} height={3300} fill="url(#fondo15)" />
                {Array.from({length: 9}).map((_, i) => <path key={i} d={`M -200 ${i * 230 - 200 + Math.sin(s * 0.5 + i) * 20} Q 540 ${i * 230 - 320} 1280 ${i * 230 - 180}`} stroke="rgba(255,200,100,0.16)" strokeWidth={5} fill="none" />)}
                <Contrato x={540} y={1000} k={3.7} />
                {palabra('SECRETO', SECRETO2, 800, 1)}
                {palabra('PRISA', PRISA, 1000, 2)}
                {palabra('ÚNICA', UNICA, 1200, 3)}
              </g>
              {quema && (
                <g>
                  <polyline points={borde.map((p) => p.join(',')).join(' ')} fill="none" stroke="#ff7a1a" strokeWidth={26} strokeLinejoin="round" opacity={0.75} />
                  <polyline points={borde.map((p) => p.join(',')).join(' ')} fill="none" stroke={GOLD} strokeWidth={12} strokeLinejoin="round" />
                  {Array.from({length: 30}).map((_, i) => {
                    const ex = i * 37 + 10 + Math.sin(s * 3 + i) * 14;
